def paired_chart(vals,linevals,maximum,unit,title):
 b=el('bars','chart-bar',''.join(f'<div class="bar" style="--v:{v}"><b>{v}{unit}</b><span>{2080+i}</span></div>' for i,v in enumerate(vals)),style=f'--max:{maximum}')
 l=el('lines','chart-line',''.join(f'<div class="pt" style="--v:{v}"><b>{v}{unit}</b><span>{2080+i}</span></div>' for i,v in enumerate(linevals)),style=f'--max:{maximum}')
 leg=el('legend','legend',f'<span class="key tone-1">{"임직원 수" if unit=="명" else "프로젝트 수"}</span><span class="key tone-2">{"고객사 수" if unit=="명" else "재계약률"}</span>')
 a=el('areas','chart-area','<div class="series tone-2"><b class="name">'+('고객사 수' if unit=='명' else '재계약률')+'</b>'+''.join(f'<div class="pt" style="--v:{v}"></div>' for v in linevals)+'</div><div class="axis">'+''.join('<span>'+str(2080+i)+'</span>' for i in range(len(linevals)))+'</div>',style=f'--max:{maximum}')
 return el('card','card','<div class="parts"><p class="name">'+title+'</p>'+a+b+l+leg+'</div>')
